"""specs_s200044.py - Sonnet-w2 family U (generated by mkfamU.py): F1 (fastcall hook that also records edx), 0x45c4b0 and INIT record the SEH chain; b is zero about half of the time; the
allocator returns 0 sometimes and otherwise a random-filled heap object. Fake outer SEH records 0-2; fs:[0] compared."""
from pilot import S
from recruits_util import rnd, clear_hooks, hook_rec, seh_record, seh_chain


def _mk(f1, init):
    def gen(c):
        clear_hooks(c)
        seh_chain(c, c.rng.choice([0, 1, 2]))
        r = c.rng
        p = r.choice([0, rnd(c, 0xc0), rnd(c, 0xc0), rnd(c, 0xc0)])
        sr = seh_record(c, 2)

        def side(emu, k):
            emu.calllog.append(('edx', emu.reg('edx')))
            sr(emu, k)
        hook_rec(c, f1, 2, ret=r.getrandbits(32), pop=8, this=True, side=side)
        hook_rec(c, 0x45c4b0, 1, ret=p, pop=0, side=seh_record(c, 2))
        hook_rec(c, init, 3, ret=r.getrandbits(32), pop=12, this=True, side=seh_record(c, 2))
        return [r.getrandbits(32), r.getrandbits(32), r.getrandbits(32), r.choice([0, 0, 1, r.getrandbits(32)])]
    return gen


S(0x4f4460, 'GUESS famU 0x4f4460', 'fastcall', None, ret='eax', gen=_mk(0x4f42f0, 0x4ee1b0), note='batch200044')
S(0x44a030, 'GUESS famU 0x44a030', 'fastcall', None, ret='eax', gen=_mk(0x449ca0, 0x45c3a0), note='batch200044')
S(0x5d8940, 'GUESS famU 0x5d8940', 'fastcall', None, ret='eax', gen=_mk(0x5d87a0, 0x43de40), note='batch200044')
